  addProperties: { id: 611, kind: 'edit', coalesce: false, family: "PropertyGroups", result: "PropertyPaths", doc: "AE's Add ▸ Property: add OPTIONAL properties that exist only once added — a text animator's Anchor Point, Skew Axis, Line Anchor, Character Value, Fill / Stroke Hue·Saturation·Brightness, Stroke Opacity, Fill Color, Stroke Color, and Font Axis properties ('axis<TAG>'). `parent` is the property group ('text/animators/<id>/props'); `names` are the new properties' path leaves. A property already present is kept as it is (AE's menu disables it). Returns the property paths in input order. Undo removes what this added." },
  removeProperties: { id: 612, kind: 'edit', coalesce: false, family: "PropertyGroups", result: "Empty", doc: "Remove optional properties (AE: select the property ▸ Delete) with their keyframes and expressions; a font axis property frees its slot. A property that is not optional is refused (`invalidArgument`). Undo restores the properties, their keys and expressions exactly." },
  pasteEffects: { id: 613, kind: 'edit', coalesce: false, family: "PropertyGroups", result: "GroupList", doc: "B3z — AE Edit ▸ Paste of copied effects from a captured SNAPSHOT (the source may since have been edited or deleted), and applying a saved effect preset. `effects` is a JSON array of captured effects — the editor's CopiedEffect: `{effect: <Effect object: type, params, enabled, opacity, maskId, labelColor, …>, tracks: {<param suffix after 'effect.<id>.'>: Keyframe[]}}` (suffix '' = the legacy single-scalar track `effect.<id>`). Every target layer gets each effect with a FRESH engine-minted id (`fx_<n>`) and fresh keyframe ids, inserted in order at stack `index` (absent = end; past the stack = `outOfRange`). The keys are written at their captured times on each target's keyframe axis (layer time — no playhead shift; the editor's paste has always done this). Returns 'effects/<id>' per pasted effect, layer-major. Undo removes them." },
  removeStroke: { id: 614, kind: 'edit', coalesce: false, family: "PropertyGroups", result: "Empty", doc: "B3z — delete Contents ▸ Stroke N of a shape's stroke stack (`layer/strokes`): the stroke and its keyframe tracks and expressions go, and the tracks of every stroke above it move down one index (strokes bind their tracks by stack index, strokeTracks.ts). `index` is 0-based; out of range is `outOfRange`. Inverse: the stack and the tracks exactly as they were." },
  addPaintStroke: { id: 615, kind: 'edit', coalesce: false, family: "PropertyGroups", result: "PaintStrokeId", doc: "B3 — PAINT STROKES (AE Effects ▸ Paint ▸ Brush N; the layer's `fx.paint`, src/core/paint/paintStrokes.ts). A stroke is document DATA: `{points: [{x, y}], color, size, opacity, hardness, mode, …}` in layer-local px, renormalised on every write (`normalizeStroke`: defaults filled, fractions clamped, v2 keys only when present). Its numeric params keep their `paint/<id>/<param>` properties (setProperty / keyframes); these commands cover what those cannot: creating, restyling and removing a stroke, its Path and the layer's Paint on Transparent.  Add one stroke at the end of the layer's paint (the Paint / Clone Stamp / Eraser tool's drag). `stroke` is a JSON object without an `id` (the engine mints `pstroke_<n>`); its `points` must be a non-empty array of finite {x, y}. `keys` are keyframes on the new stroke's numeric params in AE units (Write On: End in %) at LAYER seconds — the axis the stroke's own `inPoint`/`outPoint` use. Returns the id. Inverse: the paint and tracks as they were." },
  updatePaintStroke: { id: 616, kind: 'edit', coalesce: true, family: "PropertyGroups", result: "Empty", doc: "Merge `patch` (a JSON object) into one stroke and renormalise: a member set to null CLEARS that key (visible, pressure…); `id` cannot be patched; `points`, when given, follows addPaintStroke's rule. Shift-continue sends the joined points + pen arrays, the video switch `{visible: false}` / `{visible: null}`. Inverse: the stroke as it was." },
  removePaintStrokes: { id: 617, kind: 'edit', coalesce: false, family: "PropertyGroups", result: "Empty", doc: "Delete strokes with every track, expression and data track under `paint.<id>.`. Unknown id: `notFound`. Inverse: the strokes at their index and their tracks exactly." },
  setPaintOnTransparent: { id: 618, kind: 'edit', coalesce: false, family: "PropertyGroups", result: "Empty", doc: "AE Paint on Transparent — the layers show ONLY their paint. A layer without strokes: `notFound`." },
  setPaintStrokePath: { id: 619, kind: 'edit', coalesce: false, family: "PropertyGroups", result: "Empty", doc: "Drawing with a stroke selected REPLACES its Path (AE): with the Path animated (a `paint.<id>.path` data track), a Path key at `time` (comp time → the layer's keyframe axis); else the static points, dropping the per-point pen input recorded for the old path. `points` is a JSON array of finite {x, y}, non-empty." },
  setPaintPathAnimated: { id: 620, kind: 'edit', coalesce: false, family: "PropertyGroups", result: "Empty", doc: "The Path stopwatch: ON keys the current points at `time` (already animated: no change); OFF removes the Path keyframes (the static points stay). Inverse: the track as it was." },
  addMarkers: { id: 700, kind: 'edit', coalesce: false, family: "Markers", result: "MarkerIds", doc: "" },
